mapper.insert:

    SELECT COALESCE(MAX(team_id), 0) + 1 AS teamId FROM CLOVER_TEAM


INSERT INTO CLOVER_TEAM (
      team_id
    , team_nm
    , team_expl
    , psnl_stup_acce_yn
    , team_cmmn_stup_cn
    , team_stat
    , team_tsk_clsf
    , reg_dttm
    , regr_id
    , chng_dttm
    , chgr_id
) VALUES (
      #{teamId}
    , #{teamNm}
    , #{teamExpl}
    , #{psnlStupAcceYn}
    , #{teamCmmnStupCn}
    , #{teamStat}
    , #{teamTskClsf}
    , CURRENT_TIMESTAMP
    , #{regrId}
    , CURRENT_TIMESTAMP
    , #{chgrId}
)

mapper.update:
UPDATE CLOVER_TEAM
   SET TEAM_NM       = #{teamNm}
     , TEAM_EXPL     = #{teamExpl}
     , TEAM_TSK_CLSF = #{teamTskClsf}
     , CHGR_ID       = #{chgrId}
     , CHNG_DTTM     = CURRENT_TIMESTAMP
 WHERE TEAM_STAT     = 1
   AND TEAM_ID       = #{teamId}
